/**
 * Annotates `createRequestFunction` in a `common.ts` generated by the
 * typescript-axios generator with an explicit `Promise<R>` return type.
 *
 * `AxiosInstance.request` returns a type built on an unexported
 * `unique symbol`, so TypeScript cannot emit a declaration for the inferred
 * return type and fails with TS2527.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const replacements = [
  {
    stock:
      "(axios: AxiosInstance = globalAxios, basePath: string = BASE_PATH) => {",
    patched:
      "(axios: AxiosInstance = globalAxios, basePath: string = BASE_PATH): Promise<R> => {",
  },
  {
    stock: "return axios.request<T, R>(axiosRequestArgs);",
    patched: "return axios.request<T, R>(axiosRequestArgs) as Promise<R>;",
  },
];

const filePath = resolve(process.argv[2] ?? "common.ts");
let source = readFileSync(filePath, "utf-8");

/**
 * @param {string} text
 * @param {string} search
 */
const countOccurrences = (text, search) => text.split(search).length - 1;

for (const { stock, patched } of replacements) {
  const stockCount = countOccurrences(source, stock);
  const patchedCount = countOccurrences(source, patched);

  if (stockCount === 0 && patchedCount === 1) {
    continue;
  }

  if (stockCount !== 1 || patchedCount !== 0) {
    console.error(
      `patch-request-function: expected \`${stock}\` exactly once in ${filePath}, found it ${stockCount} times (and the patched form ${patchedCount} times)`,
    );
    process.exit(1);
  }

  source = source.replace(stock, patched);
}

writeFileSync(filePath, source);
